launcher.source:
#!/bin/bash -l
set -euo pipefail
TASK_ROOT=<scc-task>
test "$#" -eq 2
test "$1" = "$TASK_ROOT/policy-gates/qualification-plan-Linux.json"
test "$2" = "$TASK_ROOT/sources/gates-qualification/<task>/qualification-Linux"
test -L "$TASK_ROOT/sources/gates-qualification-mpi/target/tmp"
test "$(readlink -f "$TASK_ROOT/sources/gates-qualification-mpi/target/tmp")" = "$TASK_ROOT/sources/gates-qualification/target/tmp"
test "${PE:?}" = mpi_28_tasks_per_node_u
test "${NSLOTS:?}" = 28
remaining=0
case "${JOB_ID:?}" in
    8247991) first=5; last=6 ;;
    8247995) first=16; last=18 ;;
    8247996) first=19; last=21 ;;
    8247997) first=23; last=24 ;;
    8247998) first=25; last=27 ;;
    8247999) first=28; last=30 ;;
    8248000) first=32; last=33 ;;
    8248001) first=34; last=36 ;;
    8250715) first=4; last=4; remaining=3596 ;;
    8250716) first=22; last=22; remaining=3594 ;;
    8250717) first=31; last=31; remaining=3596 ;;
    *) echo 'Job is outside the authorized never-started cohort' >&2; exit 2 ;;
esac
case "${SGE_TASK_ID:?}" in ''|*[!0-9]*) exit 2 ;; esac
test "$SGE_TASK_ID" -ge "$first"
test "$SGE_TASK_ID" -le "$last"
sha256sum -c "$TASK_ROOT/policy-gates/qualification-mpi-hooks.sha256"
test -L "$TMPDIR/rsh"
test "$(readlink -f "$TMPDIR/rsh")" = /usr/local/ogs-ge2011.11.p1/sge_root/mpi/rsh
awk -v host="$(hostname -s)" '$0 != host { bad=1 } END { exit bad || NR != 28 }' "$TMPDIR/machines"
cd "$TASK_ROOT/sources/gates-qualification-mpi"
if [[ "$remaining" -gt 0 ]]; then
    timeout --signal=TERM --kill-after=10 "${remaining}s" bash -l bench/qualify.sge "$TASK_ROOT/policy-gates/qualification-plan-Linux-mpi.json" "$2"
else
    bash -l bench/qualify.sge "$TASK_ROOT/policy-gates/qualification-plan-Linux-mpi.json" "$2"
fi
sha256sum -c "$TASK_ROOT/policy-gates/qualification-mpi-hooks.sha256"
printf 'GATES_ALLOCATION_AMENDMENT_COMPLETE\n'

